import type {Event} from "./models";

/**
 * Kind is an internal rendering/data flag, not a question in the form.
 * Birthdays are exclusively generated by the linked person's birth date.
 */
export function occasionKind(name:string,existing?:Event["kind"]):Event["kind"] {
  if(existing==="holiday")return "holiday";
  const title=name.trim().toLocaleLowerCase();
  if(/(?:new year|christmas|easter|hanukkah|halloween|valentine|diwali|thanksgiving|lunar new year|новый год|рождеств|пасх|ханук|хеллоуин|святого валентина|8 марта|женский день|дивал|день благодарения)/i.test(title))return "holiday";
  return "other";
}
